<?php
if(!defined('WP_CLI')||!WP_CLI||getenv('IPL_APPLY')!=='yes'||!function_exists('ipl_credit'))throw new RuntimeException('Guarded CLI extension only.');
$before=ipl_groups();if(count($before)!==5||array_filter($before,'ipl_credit'))throw new RuntimeException('Expected existing five subscription tiles.');
function ipcc_prices($p){$v=array($p->get_regular_price('edit'),$p->get_sale_price('edit'),$p->get_price('edit'),$p->get_stock_status('edit'),$p->get_stock_quantity('edit'),$p->get_manage_stock('edit'),$p->get_meta('_ip_offer_coupons'));foreach(array('pkr','gbp') as $c)foreach(array('regular','sale') as $t)$v[]=$p->get_meta('_instapass_'.$c.'_'.$t.'_price');return $v;}
function ipcc_orders(){return hash('sha256',wp_json_encode(array_map(function($o){return $o->get_data();},wc_get_orders(array('limit'=>-1,'orderby'=>'ID','order'=>'ASC')))));}
$original=array();foreach(wc_get_products(array('status'=>array('publish','draft','private','pending'),'limit'=>-1)) as $p)$original[$p->get_id()]=array('data'=>$p->get_data(),'prices'=>ipcc_prices($p));
$orders=ipcc_orders();$file=getenv('IPL_BACKUP');if(!$file||strpos($file,'/opt/instapass/recovery/')!==0)throw new RuntimeException('Protected backup required.');file_put_contents($file,wp_json_encode(array('products'=>$original,'orders_hash'=>$orders,'groups_before'=>$before),JSON_PRETTY_PRINT));chmod($file,0600);
if(class_exists('Instapass_Notifications'))remove_action('woocommerce_update_product',array('Instapass_Notifications','restocked'));
$groups=$before;$created=array();$all=array();
foreach(array(array('claude-credits','Claude Credits','claude',144),array('chatgpt-credits','ChatGPT Credits','openai',29)) as $spec){list($key,$name,$brand,$sourceid)=$spec;$source=wc_get_product($sourceid);if(!$source)throw new RuntimeException('Missing source product.');$g=array('key'=>$key,'name'=>$name,'type'=>'credits','caption'=>'Choose your credit balance. Credits expire monthly.','enabled'=>true,'offers'=>array());
 foreach(range(50,500,25) as $amount){$existing=$key==='claude-credits'&&$amount===100;$p=$existing?wc_get_product(144):new WC_Product_Simple();$p->set_name($amount===50?$name:$name.' — $'.$amount.' credits');$p->set_status('publish');$p->set_catalog_visibility($amount===50?'visible':'hidden');$p->set_description('<p>Choose between $50 and $500 in credit balance, in $25 increments. Credits expire monthly.</p><p>The credit balance is separate from the selling price. Selling prices will be added before purchases open.</p>');$p->set_short_description('<p>Choose your credit balance. Credits expire monthly.</p>');
  if(!$existing){$p->set_sku('launch-'.$key.'-'.$amount);$p->set_virtual(true);$p->set_reviews_allowed(true);$p->set_category_ids($source->get_category_ids());$p->set_stock_status('instock');$p->update_meta_data('_ip_offer_coupons','yes');}
  foreach(array('_instapass_brand'=>$brand,'_instapass_tenor_family'=>$name,'_instapass_tenor_group'=>hash('sha256',strtolower($name)),'_instapass_validity'=>'1 month','_instapass_credit_amount'=>$amount,'_instapass_credit_expiry'=>'monthly','_instapass_access_type'=>'Private','_instapass_activation'=>'On customer email','_instapass_renewable'=>'no','_instapass_brief'=>'Credit balance from $50 to $500 · Credits expire monthly','_ip_account_allocation'=>'no','_ip_launch_family'=>$key) as $meta=>$value)$p->update_meta_data($meta,$value);
  $id=$p->save();if(!$existing)$created[]=$id;$all[]=$id;$g['offers'][$amount]=array('id'=>$id,'ready'=>false);if($amount===50)$g['parent']=$id;wc_delete_product_transients($id);
 }$groups[]=$g;
}
update_option('instapass_launch_groups',$groups,false);
foreach($original as $id=>$row)if(ipcc_prices(wc_get_product($id))!==$row['prices'])throw new RuntimeException('Existing stored prices/stock changed: '.$id);
if(ipcc_orders()!==$orders||array_slice($groups,0,5)!==$before)throw new RuntimeException('Existing orders or subscription grouping changed.');
if(count($groups)!==7||count($all)!==38||count($created)!==37||count(wc_get_products(array('status'=>'publish','visibility'=>'visible','limit'=>-1,'return'=>'ids')))!==7)throw new RuntimeException('Credit catalog shape check failed.');
file_put_contents(dirname($file).'/launch-map.json',wp_json_encode(array('groups'=>$groups,'created'=>$created),JSON_PRETTY_PRINT));
echo wp_json_encode(array('result'=>'pass','families'=>7,'credit_faces'=>38,'created_unpriced_offers'=>37,'minimum'=>50,'maximum'=>500,'step'=>25,'expiry'=>'monthly','original_prices_stock_orders_preserved'=>true,'subscription_tiles_unchanged'=>true));
